<?php use Tecnodata\Lms\Core\Csrf; ?><div class="page-heading"><div><span class="eyebrow">API-FIRST</span><h1>Integrações</h1><p>Tokens separados por sistema e escopos mínimos.</p></div></div><?php if($token):?><div class="alert alert-warning"><strong>Copie agora.</strong> Este token só será mostrado uma vez.<div class="token-box mt-2"><?=e($token)?></div></div><?php endif;?><section class="panel mb-4"><h2>Novo cliente API</h2><form method="post" action="/admin/api-clients"><?=Csrf::field()?><div class="row g-2"><div class="col-md-4"><input class="form-control" name="name" placeholder="Ex.: WooCommerce produção" required></div><div class="col-md-6"><input class="form-control" name="scopes" value="students:write,enrollments:write,enrollments:read,certification:read"></div><div class="col-md-2"><button class="btn btn-brand w-100">Gerar token</button></div></div></form></section><section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Cliente</th><th>Escopos</th><th>Último uso</th><th>Status</th></tr></thead><tbody><?php foreach($clients as $c):?><tr><td><?=e($c['name'])?></td><td><small><?=e($c['scopes_json'])?></small></td><td><?=e($c['last_used_at']?:'—')?></td><td><span class="status-badge"><?=$c['enabled']?'Ativo':'Inativo'?></span></td></tr><?php endforeach;?></tbody></table></div></section>